import Container from 'react-bootstrap/Container';
import Nav from 'react-bootstrap/Nav';
import Navbar from 'react-bootstrap/Navbar';
import "./style.css"
const Navo = ({image})=>{
return(
<>
<Navbar expand="lg" className="nav" dir="rtl">
      <Container>
        <Navbar.Brand href="#home" id="color" className="d-flex align-items-center gap-2">
          <img src={image} width={50} height={50} alt="شعار المبادرة" />
          <span>مصر في عيون طلابها</span>
        </Navbar.Brand>
        <Navbar.Toggle aria-controls="basic-navbar-nav" id='coll' />
        <Navbar.Collapse id="basic-navbar-nav" className="w-100">
          <Nav className="ms-auto d-flex justify-content-end gap-3 w-100">
            <Nav.Link href="#home" id="color">الرئيسية</Nav.Link>
            <Nav.Link href="#about" id="color">عن المبادرة</Nav.Link>
            <Nav.Link href="#projects" id="color">المشروعات القومية</Nav.Link>
            <Nav.Link href="#target" id="color">أهدافنا</Nav.Link>
          </Nav>
        </Navbar.Collapse>
      </Container>
    </Navbar>
</>
)
}
export default Navo;